PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `ui_events` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `package_name` TEXT NOT NULL, `activity_name` TEXT, `event_type` TEXT NOT NULL, `event_time` INTEGER NOT NULL, `element_id` TEXT, `element_type` TEXT, `element_text` TEXT, `element_hint` TEXT, `element_content_desc` TEXT, `element_class` TEXT, `element_bounds` TEXT, `input_value` TEXT, `selected_value` TEXT, `parent_hierarchy` TEXT, `sibling_info` TEXT, `extra_data` TEXT, `screenshot_path` TEXT);
COMMIT;